-- Zelda of Warcraft: dungeon clears and their Crystal Shards (generated by shards.py)
-- Applied by the server at startup; safe to apply again.
CREATE TABLE IF NOT EXISTS `zelda_dungeon_clear` (`map` INT UNSIGNED NOT NULL, `section` TINYINT UNSIGNED NOT NULL, `name` VARCHAR(64) NOT NULL, `item` INT UNSIGNED NOT NULL, `raid` TINYINT UNSIGNED NOT NULL DEFAULT 0, `min_x` FLOAT NOT NULL, `max_x` FLOAT NOT NULL, `min_y` FLOAT NOT NULL, `max_y` FLOAT NOT NULL, PRIMARY KEY (`map`, `section`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
DELETE FROM `zelda_dungeon_clear`;
DELETE FROM `item_template` WHERE `entry` IN (191100,191101,191102,191103,191104,191105,191106,191107,191108,191109,191110,191111,191112,191113,191114,191115,191116,191117,191118,191119,191120,191121,191122,191123,191124,191125,191126,191127,191128,191129,191130);
